vector<int> maxSlidingWindow(vector<int>& a, int k) {
    deque<int> d; vector<int> out;
    for (int i = 0; i < (int)a.size(); i++) {
        while (!d.empty() && a[d.back()] <= a[i]) d.pop_back();
        d.push_back(i);
        if (d.front() <= i - k) d.pop_front();
        if (i >= k - 1) out.push_back(a[d.front()]);
    }
    return out;
}
